using IngSoft.Api.Data; using IngSoft.Api.DTOs; using IngSoft.Api.Entities; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace IngSoft.Api.Controllers;
[ApiController, Route("api/productos")]
public class ProductosController(AppDbContext db) : ControllerBase
{
    [HttpGet, ProducesResponseType(typeof(IEnumerable<ProductoDto>),200)] public async Task<IActionResult> Get() => Ok(await db.Productos.AsNoTracking().Select(x=>new ProductoDto(x.IdProducto,x.Descripcion,x.PrecioMinorista,x.StockActual,x.StockMinimo,x.StockActual<=x.StockMinimo)).ToListAsync());
    [HttpGet("{id:int}"), ProducesResponseType(typeof(ProductoDto),200), ProducesResponseType(404)] public async Task<IActionResult> Get(int id) { var x=await db.Productos.AsNoTracking().FirstOrDefaultAsync(p=>p.IdProducto==id); return x is null ? NotFound(new ErrorResponse("Producto no encontrado.",404)) : Ok(new ProductoDto(x.IdProducto,x.Descripcion,x.PrecioMinorista,x.StockActual,x.StockMinimo,x.StockActual<=x.StockMinimo)); }
    [HttpPost, ProducesResponseType(typeof(ProductoDto),201), ProducesResponseType(400), ProducesResponseType(404)] public async Task<IActionResult> Save(ProductoRequest r) { Producto x; var status=201; if(r.IdProducto is int id){x=await db.Productos.FindAsync(id)??null!;if(x is null)return NotFound(new ErrorResponse("Producto no encontrado.",404));status=200;}else{x=new();db.Productos.Add(x);} x.Descripcion=r.Descripcion;x.PrecioMinorista=r.PrecioMinorista;x.StockActual=r.StockActual;x.StockMinimo=r.StockMinimo;await db.SaveChangesAsync();var dto=new ProductoDto(x.IdProducto,x.Descripcion,x.PrecioMinorista,x.StockActual,x.StockMinimo,x.StockActual<=x.StockMinimo);return status==201?Created($"/api/productos/{x.IdProducto}",dto):Ok(dto); }
    [HttpDelete("{id:int}"), ProducesResponseType(204), ProducesResponseType(404), ProducesResponseType(400)] public async Task<IActionResult> Delete(int id) { var x=await db.Productos.FindAsync(id); if(x is null)return NotFound(new ErrorResponse("Producto no encontrado.",404)); if(await db.DetallesItems.AnyAsync(d=>d.IdProducto==id))return BadRequest(new ErrorResponse("No se puede eliminar un producto utilizado en pedidos.",400)); db.Productos.Remove(x); await db.SaveChangesAsync(); return NoContent(); }
}
